sequence.script:
var now = new Date().toISOString();

function text(value, fallback) {
    if (value === null || value === undefined || String(value).length === 0) {
        return fallback;
    }

    return String(value);
}

var errorCode = text(mc.getProperty('ERROR_CODE'), 'BACKEND_UNAVAILABLE');
var errorMessage = text(
    mc.getProperty('ERROR_MESSAGE') || mc.getProperty('ERROR_DETAIL'),
    'Backend endpoint is unavailable or did not respond.'
);

mc.setPayloadJSON({
    name: 'loans-api',
    version: '1.0.0',
    domain: '',
    owner: '',
    ownerEmail: '',
    runtime: '',
    criticality: '',
    checkFrequency: '',
    healthUrl: '',
    contractUrl: '',
    expectedHttpStatus: 200,
    slaTargetMs: 300,
    consumerStatus: 'RED',
    checkedAt: now,
    source: 'wso2-integrator',
    liveness: {
        status: 'ERROR',
        httpStatus: 0,
        responseTimeMs: 0,
        checkedAt: now,
        reasons: [
            'Liveness check failed because the backend endpoint is unavailable.',
            errorCode + ': ' + errorMessage
        ]
    },
    contract: {
        status: 'SKIPPED',
        checkedAt: now,
        reasons: [
            'Contract validation skipped because liveness check failed.'
        ]
    },
    sla: {
        status: 'BREACHED',
        checkedAt: now,
        targetMs: 300,
        actualMs: 0
    }
});
